package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import android.text.InputType;import org.json.*;import java.lang.reflect.*;
public final class EditorExtras {
 private static JSONObject selected;private static boolean armed;
 public static void select(JSONObject p){selected=p;armed=true;}
 public static void builder(AlertDialog.Builder b){if(armed&&selected!=null){armed=false;b.setNeutralButton("Body & motion",null);}}
 public static void decorate(final Activity a,AlertDialog d){Button b=d.getButton(-3);if(b!=null&&"Body & motion".contentEquals(b.getText())){final JSONObject p=selected;b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){open(a,p);}});}}
 private static String manage(Activity a,String action,JSONObject p)throws Exception{return (String)Class.forName("org.efootballrevival.runtimeprobe.EmbeddedGateway").getMethod("manage",Context.class,String.class,String.class).invoke(null,a,action,p.toString());}
 private static void error(Activity a,Exception e){new AlertDialog.Builder(a).setTitle("Could not apply settings").setMessage(e.getCause()!=null?String.valueOf(e.getCause().getMessage()):String.valueOf(e.getMessage())).setPositiveButton("Close",null).show();}
 private static EditText number(Activity a,LinearLayout l,String title,int value){TextView t=new TextView(a);t.setText(title);l.addView(t);EditText e=new EditText(a);e.setInputType(InputType.TYPE_CLASS_NUMBER);e.setText(String.valueOf(value));l.addView(e);return e;}
 private static Spinner choice(Activity a,LinearLayout l,String title,String[] labels,int pos){TextView t=new TextView(a);t.setText(title);l.addView(t);Spinner sp=new Spinner(a);ArrayAdapter<String> ad=new ArrayAdapter<String>(a,android.R.layout.simple_spinner_item,labels);ad.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);sp.setAdapter(ad);sp.setSelection(Math.max(0,pos));l.addView(sp);return sp;}
 public static void open(final Activity a,final JSONObject p){if(p==null)return;new Thread(new Runnable(){public void run(){try{final JSONObject data=new JSONObject(manage(a,"v25_body_get",p));a.runOnUiThread(new Runnable(){public void run(){try{form(a,p,data);}catch(Exception e){error(a,e);}}});}catch(final Exception e){a.runOnUiThread(new Runnable(){public void run(){error(a,e);}});}}},"BodySettings").start();}
 private static void form(final Activity a,final JSONObject p,JSONObject data)throws Exception{
  ScrollView scroll=new ScrollView(a);LinearLayout col=new LinearLayout(a);col.setOrientation(1);int pad=(int)(20*a.getResources().getDisplayMetrics().density);col.setPadding(pad,pad,pad,pad);scroll.addView(col);
  final EditText height=number(a,col,"Height (140–220 cm)",data.getInt("height"));final EditText weight=number(a,col,"Weight (40–130 kg)",data.getInt("weight"));
  final Spinner foot=choice(a,col,"Stronger foot",new String[]{"Right","Left"},data.getInt("foot"));
  final JSONArray celebrations=data.getJSONArray("celebrations");String[] names=new String[celebrations.length()];int current=0;for(int i=0;i<names.length;i++){JSONObject r=celebrations.getJSONObject(i);names[i]=r.getString("label");if(r.getInt("id")==data.getInt("celebration"))current=i;}
  final Spinner celebrate=choice(a,col,"Native celebration preset",names,current);
  final Spinner sleeve=choice(a,col,"Sleeves",new String[]{"Keep original","Short","Long"},data.getInt("sleeve_index"));
  final Spinner[] gear=new Spinner[4];String[] labels={"Left wrist tape","Right wrist tape","Ankle tape","Outfield player gloves"};JSONObject existingGear=data.optJSONObject("accessories");for(int i=0;i<4;i++)gear[i]=choice(a,col,labels[i],new String[]{"Keep original","Off","On (original color)"},existingGear==null?0:existingGear.optInt(String.valueOf(i+4),0));
  TextView note=new TextView(a);note.setText("Applies to this card ID in matches. Other copies of the same card share physical settings. Save before entering the game. Native celebration labels identify the source preset; animation needs device verification.");col.addView(note);
  final AlertDialog d=new AlertDialog.Builder(a).setTitle("Body & motion · "+p.optString("name_en",p.optString("name","Player"))).setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.show();d.getButton(-1).setOnClickListener(new View.OnClickListener(){public void onClick(View v){try{final JSONObject req=new JSONObject(p.toString());req.put("height",Integer.parseInt(height.getText().toString()));req.put("weight",Integer.parseInt(weight.getText().toString()));req.put("foot",foot.getSelectedItemPosition());req.put("celebration",celebrations.getJSONObject(celebrate.getSelectedItemPosition()).getInt("id"));req.put("sleeve",new String[]{"none","short","long"}[sleeve.getSelectedItemPosition()]);JSONObject acc=new JSONObject();for(int i=0;i<4;i++)acc.put(String.valueOf(i+4),gear[i].getSelectedItemPosition());req.put("accessories",acc);d.getButton(-1).setEnabled(false);new Thread(new Runnable(){public void run(){try{manage(a,"v25_body_apply",req);a.runOnUiThread(new Runnable(){public void run(){d.dismiss();Toast.makeText(a,"Saved. Reopen the player to check the values.",Toast.LENGTH_LONG).show();}});}catch(final Exception e){a.runOnUiThread(new Runnable(){public void run(){d.getButton(-1).setEnabled(true);error(a,e);}});}}},"SaveBodySettings").start();}catch(Exception e){error(a,e);}}});
 }
}
